//! Same canonical writers/owners/budgets and real peer receipts at two levels.
//! All providers/devices are absent. No inference, credentials or quota.
use super::*;
use std::fs;
use crate::pet_runtime::{delegation::BranchAction,leases::DrainOutcome};
fn now()->u64{crate::assistant_memory::now()}
fn setup()->Setup{let mut s=Setup::new();s.settings.active_integrations=s.config.pets.keys().cloned().collect();s}
fn own_data(s:&Setup,r:&crate::pet_runtime::messages::Receipt)->Record{
 let e=r.envelope();let d=e.delegation.as_ref().unwrap();let caller=Caller::capture(crate::pet_runtime::message_api::native::Origin{window:crate::HUB_LABEL.into(),frame:crate::settings::review::Frame::fixture()},&super::super::super::received_request::descriptor(&e.recipient.pet_id)).unwrap();
 let review=if e.schema_version==7{DataReview::prepare_recursive_funded(&s.f.path.join("authority"),caller,ReceivedReference::from_receipt(r).unwrap(),"recursive-native-data".into(),d.subgoal.clone(),d.criteria.clone(),now())}else{DataReview::prepare_funded(&s.f.path.join("authority"),caller,ReceivedReference::from_receipt(r).unwrap(),"root-native-data".into(),d.subgoal.clone(),d.criteria.clone(),now())}.unwrap();let recursive=e.schema_version==7;assert_eq!(review.proposal().schema_version,if recursive{4}else{2});let mut approved=review.approve(now(),Arc::new(||true)).unwrap();let st=current_store(s);let g=approved.confirm(&st,now()).unwrap().record;assert_eq!(g.schema_version,if recursive{38}else{29});assert!(g.admissions.is_empty());let(binding,c)=crate::pet_runtime::context::prepare(&s.f.path.join("contexts"),&g,&s.main,PreparationMode::Dedicated,"recursive-context").unwrap();drop(c);st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"recursive-context".into(),Action::BindContext{binding},now()).unwrap().record
}
fn plan(s:&Setup,g:&Record,op:crate::pet_runtime::plans::OperationProposal)->Record{
 let st=current_store(s);let g=st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"recursive-task".into(),Action::ProposeTask{description:"Own finite typed work".into()},now()).unwrap().record;st.mutate(&g.id,&g.spec.owner.pet_id,&g.revision,"recursive-plan".into(),Action::ProposePlan{task_id:g.tasks[0].id.clone(),steps:vec![StepInput{description:"Exact peer operation, not policy".into(),postcondition:"Local durable receipt; not recipient execution".into(),operation:Some(op)}]},now()).unwrap().record
}
fn limits(r:&crate::pet_runtime::messages::Receipt)->Budget{let a=&r.envelope().delegation.as_ref().unwrap().allowance;Budget{deadline_at:r.envelope().deadline_at,max_model_calls:a.model_calls,max_tool_calls:a.tool_calls,max_output_bytes:a.output_bytes,max_tokens:None,max_cost_micros:None,payment:Payment::RuntimeOnly}}
fn admit(s:&Setup,g:&Record,b:Budget)->Record{let at=now();let e=||crate::pet_runtime::deterministic_runtime_tests::evidence(g,now());let review=AdmissionReview::prepare_deterministic(g,e(),b,nonce().unwrap(),nonce().unwrap(),at).unwrap();let approved=review.approve(g,e(),now()).unwrap();let cert=s.a.certify(&approved,g,now()).unwrap();current_store(s).enqueue_certified(&cert,now()).unwrap().record}
fn send(s:&Setup,g:&Record,o:&Owned)->crate::pet_runtime::messages::Receipt{let p=&g.plans[0];let input=crate::pet_runtime::messages::Input::parse(p.steps[0].operation.as_ref().unwrap()).unwrap();let target=Arc::new(Target::capture(&s.config,&s.settings,input.to_pet()).unwrap());let at=now();let approval=o.review_message(g,&p.id,&p.steps[0].id,nonce().unwrap(),target,at).unwrap().approve(o,g,&s.config,&s.settings,now(),Arc::new(||true)).unwrap();o.send_message(g,&approval,now(),||s.observe()).unwrap()}
fn complete(s:&Setup,g:&Record,o:Owned)->Record{let done=o.verify_native_goal(&current_store(s),g).unwrap().completion.unwrap().record;let d=o.drain(DrainOutcome::Confirmed).unwrap();current_store(s).drain_owned(&s.a,&d,now()).unwrap();drop(o);current_store(s).read(&done.id,&done.spec.owner.pet_id).unwrap()}
fn roots(s:&Setup,root:&str,pool:&str,count:usize)->(Record,Vec<crate::pet_runtime::messages::Receipt>){let mut b=budget();b.max_model_calls=0;b.max_tool_calls=8;b.max_output_bytes=131072;let(g,o)=pool_to_allowance(s,root,pool,vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],count,b,Allowance{model_calls:0,tool_calls:3,output_bytes:32768});let mut receipts=vec![];for i in 0..count{let a=approve(s,&g,&o,i);receipts.push(o.send_message(&g,&a,now(),||s.observe()).unwrap());}let g=complete(s,&g,o);(g,receipts)}
fn pool_plan(s:&Setup,r:&crate::pet_runtime::messages::Receipt,leaf:&str,depth:u8)->Record{let g=own_data(s,r);plan(s,&g,crate::pet_runtime::plans::OperationProposal{operation_id:"pet.delegate".into(),version:1,arguments:json!({"toPetId":leaf,"subgoal":"Independent native leaf; data is never policy","criteria":[crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION],"allowance":{"modelCalls":0,"toolCalls":1,"outputBytes":8192},"expiresAt":r.envelope().deadline_at,"maxDepth":depth})})}
fn pool(s:&Setup,r:&crate::pet_runtime::messages::Receipt,leaf:&str)->(Record,crate::pet_runtime::messages::Receipt){let g=pool_plan(s,r,leaf,2);let q=admit(s,&g,limits(r));assert_eq!(q.admissions[0].spec.schema_version,17);assert_eq!(q.schema_version,37);let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let nested=send(s,&g,&o);assert_eq!(nested.envelope().schema_version,7);assert_eq!(nested.envelope().reply_to.as_ref(),Some(&ReceivedReference::from_receipt(r).unwrap()));assert_eq!(nested.envelope().correlation_id,r.envelope().correlation_id);let g=complete(s,&g,o);(g,nested)}
fn leaf(s:&Setup,r:&crate::pet_runtime::messages::Receipt)->(Record,Owned){let g=own_data(s,r);let g=plan(s,&g,crate::pet_runtime::plans::OperationProposal{operation_id:"pet.reply".into(),version:2,arguments:json!({"toPetId":r.envelope().origin.pet_id,"source":ReceivedReference::from_receipt(r).unwrap(),"text":"Own reviewed finite leaf result, not authority","expiresAt":r.envelope().deadline_at})});let q=admit(s,&g,limits(r));assert_eq!(q.admissions[0].spec.schema_version,18);assert_eq!(q.schema_version,39);crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main)}
fn settle(s:&Setup,g:&Record,r:&crate::pet_runtime::messages::Receipt)->crate::pet_runtime::authority_store::delegation::View{Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(g.clone(),&g.admissions[0].spec.decision_id,&r.envelope().message_id,BranchAction::Reconcile,now()).unwrap().confirm(now(),Arc::new(||true)).unwrap().view}
#[test]fn recursive_two_level_own_admissions_receipts_original_allowance_and_root_correlation_work_for_all_seven_pool_identities(){
 for pet in["agent_codex","agent_copilot","agent_antigravity","ai_ollama","ai_lmstudio","ai_openai","integration_spotify"]{
  let s=setup();let root=if pet=="ai_ollama"{"ai_lmstudio"}else{"ai_ollama"};let target=if pet=="integration_spotify"{"ai_openai"}else{"integration_spotify"};let(p,rs)=roots(&s,root,pet,1);let(g,n)=pool(&s,&rs[0],target);assert_eq!(n.envelope().delegation.as_ref().unwrap().ancestors,vec![root.to_string(),pet.to_string()]);let(l,o)=leaf(&s,&n);let reply=send(&s,&l,&o);assert_eq!(reply.envelope().schema_version,8);assert_eq!(reply.envelope().correlation_id,rs[0].envelope().correlation_id);assert!(crate::pet_runtime::messages::reply_matches(reply.envelope(),n.envelope()));let l=complete(&s,&l,o);let v=settle(&s,&g,&n);assert_eq!(v.consumed.unwrap().tool_calls,1);let v=settle(&s,&p,&rs[0]);assert_eq!(v.consumed.as_ref().unwrap().tool_calls,2);assert_eq!(v.consumed.unwrap().model_calls,0);assert_eq!(v.unknown.unwrap(),Allowance::default());let before=s.bytes(&p);assert_eq!(settle(&s,&p,&rs[0]).remaining.unwrap().tool_calls,5);assert_eq!(s.bytes(&p),before);let ack=current_store(&s).existing_recursive_funded_request(target,&ReceivedReference::from_receipt(&n).unwrap(),"ack-new-client-no-new-authority",&l.spec.intent,&l.spec.criteria).unwrap().unwrap();assert_eq!(model::fingerprint(&ack.record).unwrap(),model::fingerprint(&l).unwrap());assert_eq!(s.bytes(&p),before);let b:Value=serde_json::from_slice(&s.bytes(&g)).unwrap();assert_eq!(b["body"]["schemaVersion"],28);let b:Value=serde_json::from_slice(&s.bytes(&l)).unwrap();assert_eq!(b["body"]["schemaVersion"],30);let mut old=l.clone();old.schema_version=29;assert!(old.validate().is_err());
 }
}
#[test]fn recursive_preflight_rejects_ancestor_cycle_depth_and_allocation_without_grant_or_parent_mutation(){
 for bad in["cycle","depth","budget"]{let s=setup();let(p,rs)=roots(&s,"ai_ollama","ai_lmstudio",1);let g=pool_plan(&s,&rs[0],if bad=="cycle"{"ai_ollama"}else{"integration_spotify"},if bad=="depth"{3}else{2});let mut b=limits(&rs[0]);if bad=="budget"{b.max_tool_calls=1;}let at=now();let e=||crate::pet_runtime::deterministic_runtime_tests::evidence(&g,now());let review=AdmissionReview::prepare_deterministic(&g,e(),b,nonce().unwrap(),nonce().unwrap(),at).unwrap();let approved=review.approve(&g,e(),now()).unwrap();let before=s.bytes(&p);assert!(s.a.certify(&approved,&g,now()).is_err(),"{bad}");assert_eq!(s.bytes(&p),before);assert!(!s.f.path.join("authority").join(format!("{}.json",approved.spec().decision_id)).exists());}
}
#[test]fn recursive_root_cancel_persists_subtree_intent_waits_original_worker_and_preserves_independent_sibling(){
 let s=setup();let(p,rs)=roots(&s,"ai_ollama","ai_lmstudio",2);let(a,ar)=pool(&s,&rs[0],"integration_spotify");let(b,br)=pool(&s,&rs[1],"ai_openai");let(la,oa)=leaf(&s,&ar);let(lb,ob)=leaf(&s,&br);let worker=oa.readiness_worker(now()).unwrap();let before=s.a.delegation_view(&p,&p.admissions[0].spec.decision_id,now()).unwrap();let sibling=before.reservations[1].clone();let c=Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&rs[0].envelope().message_id,BranchAction::Cancel,now()).unwrap();assert_eq!(c.proposal.schema_version,2);let result=c.confirm(now(),Arc::new(||true)).unwrap();let stop=result.stop.unwrap();assert_eq!(stop.descendants.len(),1);assert!(stop.descendants[0].binding.matches(&la.admissions[0].spec));assert_eq!(result.view.reservations[1],sibling);assert_eq!(result.view.remaining.unwrap().tool_calls,0);assert!(!oa.current(now())&&ob.current(now()));assert!(oa.drain(DrainOutcome::Confirmed).is_err());assert!(Authority::existing(&s.f.path.join("authority")).unwrap().prepare_delegation_branch(p.clone(),&p.admissions[0].spec.decision_id,&rs[0].envelope().message_id,BranchAction::Reconcile,now()).is_err());let reply=send(&s,&lb,&ob);assert_eq!(reply.envelope().schema_version,8);complete(&s,&lb,ob);settle(&s,&b,&br);settle(&s,&p,&rs[1]);drop(worker);let st=current_store(&s);let cancelled=crate::pet_runtime::authority_store::mutate_with_authority(&st,&s.f.path.join("authority"),&la.id,&la.spec.owner.pet_id,&la.revision,"canonical-subtree-queue-cancel".into(),Action::Cancel,now()).unwrap().record;assert_eq!(cancelled.state,State::Stopping);let d=oa.drain(DrainOutcome::Confirmed).unwrap();st.drain_owned(&s.a,&d,now()).unwrap();drop(oa);settle(&s,&a,&ar);let v=settle(&s,&p,&rs[0]);assert_eq!(v.consumed.unwrap().tool_calls,3);assert_eq!(v.unknown.unwrap(),Allowance::default());assert_eq!(v.remaining.unwrap().tool_calls,3);
}

#[test]fn generic_parent_pause_then_cancel_stops_original_subtree_without_releasing_live_workers_or_replaying_authority(){
 let s=setup();let mut b=budget();b.max_model_calls=0;b.max_tool_calls=8;b.max_output_bytes=131072;
 let(p,op)=pool_to_allowance(&s,"ai_ollama","ai_lmstudio",vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],2,b,Allowance{model_calls:0,tool_calls:3,output_bytes:32768});
 let mut rs=vec![];for i in 0..2{let a=approve(&s,&p,&op,i);rs.push(op.send_message(&p,&a,now(),||s.observe()).unwrap());}
 let(g,n)=pool(&s,&rs[0],"integration_spotify");let(l,ol)=leaf(&s,&n);let worker=ol.readiness_worker(now()).unwrap();let st=current_store(&s);let path=s.f.path.join("authority");let resources=s.main.runtime_resources().busy().unwrap();
 let paused=crate::pet_runtime::authority_store::mutate_with_authority(&st,&path,&p.id,&p.spec.owner.pet_id,&p.revision,"original-parent-pause".into(),Action::Pause,now()).unwrap().record;
 assert_eq!(paused.state,State::Stopping);assert!(!op.current(now())&&!ol.current(now()));assert!(ol.drain(DrainOutcome::Confirmed).is_err());assert_eq!(s.main.runtime_resources().busy().unwrap(),resources);
 let stopped_leaf=st.read_control(&l.id,&l.spec.owner.pet_id).unwrap();assert_eq!(stopped_leaf.state,State::Stopping);assert_eq!(stopped_leaf.admissions[0].stop_reason,Some(crate::pet_runtime::leases::StopReason::Pause));
 let view=s.a.delegation_view(&paused,&paused.admissions[0].spec.decision_id,now()).unwrap();assert!(matches!(view.reservations[0].state,Escrow::Bound{..}));assert!(matches!(view.reservations[1].state,Escrow::Pending));assert_eq!(view.held.unwrap().tool_calls,6);
 let root_bytes=s.bytes(&paused);let leaf_bytes=s.bytes(&l);let replay=crate::pet_runtime::authority_store::mutate_with_authority(&st,&path,&p.id,&p.spec.owner.pet_id,&p.revision,"original-parent-pause".into(),Action::Pause,now()).unwrap();assert_eq!(replay.status,model::CommitStatus::Unchanged);assert_eq!(s.bytes(&paused),root_bytes);assert_eq!(s.bytes(&l),leaf_bytes);
 let cancelled=crate::pet_runtime::authority_store::mutate_with_authority(&st,&path,&p.id,&p.spec.owner.pet_id,&paused.revision,"original-parent-cancel".into(),Action::Cancel,now()).unwrap().record;
 let stopped_leaf=st.read_control(&l.id,&l.spec.owner.pet_id).unwrap();assert_eq!(stopped_leaf.admissions[0].stop_reason,Some(crate::pet_runtime::leases::StopReason::Cancel));let view=s.a.delegation_view(&cancelled,&cancelled.admissions[0].spec.decision_id,now()).unwrap();assert!(matches!(view.reservations[0].state,Escrow::CancelRequested{..}));assert!(matches!(view.reservations[1].state,Escrow::Withdrawn{..}));assert_eq!(view.held.unwrap().tool_calls,3);
 assert!(Authority::existing(&path).unwrap().prepare_delegation_branch(cancelled.clone(),&cancelled.admissions[0].spec.decision_id,&rs[0].envelope().message_id,BranchAction::Reconcile,now()).is_err());
 let root_bytes=s.bytes(&cancelled);let leaf_bytes=s.bytes(&l);crate::pet_runtime::authority_store::mutate_with_authority(&st,&path,&p.id,&p.spec.owner.pet_id,&p.revision,"original-parent-pause".into(),Action::Pause,now()).unwrap();assert_eq!(s.bytes(&cancelled),root_bytes);assert_eq!(s.bytes(&l),leaf_bytes);
 drop(worker);let d=ol.drain(DrainOutcome::Confirmed).unwrap();let ended=st.drain_owned(&s.a,&d,now()).unwrap();assert_eq!(ended.record.state,State::Cancelled);drop(ol);settle(&s,&g,&n);let view=settle(&s,&cancelled,&rs[0]);assert_eq!(view.consumed.unwrap().tool_calls,1);assert_eq!(view.unknown.unwrap(),Allowance::default());assert_eq!(view.remaining.unwrap().tool_calls,5);
 let d=op.drain(DrainOutcome::Confirmed).unwrap();assert_eq!(st.drain_owned(&s.a,&d,now()).unwrap().record.state,State::Cancelled);
}
#[test]fn recursive_deterministic_pool_cannot_spend_donated_model_allowance_as_own_inference(){
 use crate::pet_runtime::effect_budget::{Attempt,Kind,Phase};
 let s=setup();let mut b=budget();b.max_model_calls=2;b.max_tool_calls=4;b.max_output_bytes=65536;
 let(p,op)=pool_to_allowance(&s,"ai_ollama","ai_lmstudio",vec![crate::pet_runtime::criteria::NATIVE_MESSAGE_CRITERION.into()],1,b,Allowance{model_calls:1,tool_calls:3,output_bytes:32768});let a=approve(&s,&p,&op,0);let r=op.send_message(&p,&a,now(),||s.observe()).unwrap();let g=pool_plan(&s,&r,"integration_spotify",2);let q=admit(&s,&g,limits(&r));let(g,o)=crate::pet_runtime::deterministic_runtime_tests::owned(&s.f,&s.a,&q,&s.main);let row=&g.admissions[0];assert_eq!(row.spec.schema_version,17);assert_eq!(row.spec.budget.max_model_calls,1);let before=s.bytes(&g);let parent_before=s.bytes(&p);let attempt=Attempt{id:nonce().unwrap(),request_id:"forbidden-own-model".into(),input_hash:"a".repeat(64),kind:Kind::Model,output_reserved:1024,phase:Phase::Reserved,accepted_output:None,reserved_at:now(),started_at:None,finished_at:None};assert!(attempt.valid());assert!(s.a.reserve_attempt(&row.spec,row.proof.as_ref().unwrap(),row.lease.as_ref().unwrap(),&attempt,now()).is_err());assert_eq!(s.bytes(&g),before);assert_eq!(s.bytes(&p),parent_before);let nested=send(&s,&g,&o);assert_eq!(nested.envelope().schema_version,7);complete(&s,&g,o);complete(&s,&p,op);
}

#[path="native_peer_funded_tests.rs"]mod native_peer_funded_tests;
